def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def wrapper(func):
        cache = {}
        def memoized_func(*args):
            nonlocal cache
            key = args if typed else tuple(args)  # Generate a tuple for hashable objects
            if key in cache:
                cache[key] = (cache[key][0] + 1, func(*args)) if key in cache else (0, func(*args))
                if cache[key][0] == maxsize:
                    cache.popitem(last=False)
            else:
                cache[key] = (0, func(*args))
            return cache[key][1]
        return memoized_func
    return wrapper
