    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for observed_key, expected_keys in observer_schema.items():
        if observed_key not in response:
            raise KeyError(f"Observed field '{observed_key}' is not present in the Kubernetes response")
        if isinstance(expected_keys, str):
            last_applied_manifest[observed_key] = response[expected_keys]
        elif isinstance(expected_keys, list):
            if not all(key in response for key in expected_keys):
                raise KeyError(f"One or more expected fields are not present in the Kubernetes response")
            last_applied_manifest[observed_key] = {key: response[key] for key in expected_keys}
        else:
            raise TypeError(f"Expected_keys should be a string or a list, got {type(expected_keys)}")
