def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Args:
        validate_objects (bool, optional): Whether to validate each object's existence and integrity. Defaults to True.
        check_digests (bool, optional): Whether to check each object's digest. Defaults to True.
        show_warnings (bool, optional): Whether to show warnings about missing objects or ignored digests. Defaults to False.

    Returns:
        num_objects - Number of objects checked
        good_objects - Number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Walk through all objects in the storage root hierarchy
    for object_path in self.storage_root_walk():
        num_objects += 1
        if validate_objects:
            if not self.object_exists(object_path):
                print(f"Warning: Object {object_path} does not exist.")
                if not show_warnings:
                    continue
            if not self.object_valid(object_path):
                print(f"Warning: Object {object_path} is not valid.")
                if not show_warnings:
                    continue
                good_objects += 1

        if check_digests:
            if not self.object_has_digest(object_path):
                print(f"Warning: Object {object_path} does not have a digest.")
                if not show_warnings:
                    continue
            if self.object_digest_mismatch(object_path):
                print(f"Warning: Object {object_path} has a mismatched digest.")
                if not show_warnings:
                    continue
                good_objects += 1

    return num_objects, good_objects
