def deep_merge_nodes(nodes):
    yaml = YAML()
    data = yaml.load(dump_nodes(nodes))

    def merge_mappings(lhs, rhs):
        if not isinstance(lhs, MappingNode):
            return rhs
        if not isinstance(rhs, MappingNode):
            return lhs
        result = MappingNode()
        for key, value in lhs.items():
            result[key] = merge_mappings(value, rhs.get(key, value))
