class RandomizedCollection:
    def __init__(self):
        # Initialize with a deque used as a stack to store elements
        self.elements = deque()

    def insert(self, val: int) -> bool:
        # Check if the element is already in the collection
        if val in self.elements:
            return False
        # Append the element to the deque and increase the count
        self.elements.append(val)
        return True

    def remove(self, val: int) -> bool:
        # Check if the element is in the collection
        if val not in self.elements:
            return False
        # Remove the element from the deque
        self.elements.remove(val)
        return True

    def getRandom(self) -> int:
        # Randomly select an element from the deque
        if not self.elements:
            return None
        return self.elements[randint(0, len(self.elements) - 1)]
